        let fresh = now - self.ttl_secs;
        self.entries.retain(|(_, _, at)| *at > fresh);
        self.entries
            .iter()
            .find(|(existing, _, _)| existing == key)
            .map(|(_, capabilities, _)| capabilities.clone())
