    fn execute(&self, call: &Call) -> Result<Output> {
        let text = match call.tool {
            Tool::Read => {
                let path = self.resolve(call.need("path")?)?;
                let text = std::fs::read_to_string(&path).map_err(|e| Error::io(&path, e))?;
