pub mod citation {
    //! A requirement's citation added with no test that fails without it
    //! (`V-15`).
    //!
    //! Cycle 9 closed `X-13` with nine lines of prose: a module-doc paragraph
    //! asserting `shell` was confined to the workspace, and `X-13` added to
    //! the file's requirement header. No code, no test. Every gate went
    //! green — a false docstring compiles — and `perp check ids` passed,
    //! because the id it cited is defined. Neither check reads the claim
    //! against anything; this one does, on the one artefact that exists at
    //! decision time: the diff itself.
    //!
    //! A citation is a claim about behaviour. What makes it more than a
    //! sentence is a test that fails without the change — so a diff that
    //! introduces an id and adds no test anywhere in the same change is
    //! exactly the shape `X-13` was, whatever the prose around it says.

    use std::collections::BTreeSet;

    /// A requirement id newly cited in a diff that added no test.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
    pub struct Bare {
        pub id: String,
        pub file: String,
    }

    /// Split a unified diff into `(path, hunk-text)` per file, keyed on the
    /// post-image path from `+++ b/...` — the same path a citation or a test
    /// added in that file would be read under.
    fn split_by_file(diff: &str) -> Vec<(String, String)> {
        let mut files = Vec::new();
        let mut current: Option<String> = None;
        let mut hunk = String::new();
        for line in diff.lines() {
            if line.starts_with("diff --git ") {
                if let Some(path) = current.take() {
                    files.push((path, std::mem::take(&mut hunk)));
                }
                continue;
            }
            if let Some(path) = line.strip_prefix("+++ b/") {
                current = Some(path.to_string());
                continue;
            }
            if current.is_some() {
                hunk.push_str(line);
                hunk.push('\n');
            }
        }
        if let Some(path) = current.take() {
            files.push((path, hunk));
        }
        files
    }

    /// Ids that appear on a `+` line of this file's hunk and did not already
    /// appear on a `-` line — a citation actually added, not one only moved.
    fn added_ids(hunk: &str) -> BTreeSet<String> {
        let mut added = BTreeSet::new();
        let mut removed = BTreeSet::new();
        for line in hunk.lines() {
            if let Some(rest) = line.strip_prefix('+') {
                if rest.starts_with('+') {
                    continue;
                }
                added.extend(super::ids_in(rest));
            } else if let Some(rest) = line.strip_prefix('-') {
                if rest.starts_with('-') {
                    continue;
                }
                removed.extend(super::ids_in(rest));
            }
        }
        added.difference(&removed).cloned().collect()
    }

    /// A path a reasonable test for this project lives under. Blunt on
    /// purpose, the same way `tamper` is: the shape this exists to catch is
    /// zero test lines anywhere in the change, and a false positive here
    /// costs a second look rather than a shipped hole.
    fn is_test_file(path: &str) -> bool {
        path.contains("/tests/")
            || path.starts_with("tests/")
            || path.contains("test_")
            || path.contains("_test.")
            || path.contains("_tests.")
    }

    fn added_line(line: &str) -> Option<&str> {
        let rest = line.strip_prefix('+')?;
        if rest.starts_with('+') {
            return None;
        }
        Some(rest)
    }

    /// Whether the whole diff adds a test: a new `#[test]` function anywhere,
    /// or an added line inside a file whose path names it as a test. Either
    /// is evidence a claim was checked; neither was true of `X-13`.
    fn diff_adds_a_test(files: &[(String, String)]) -> bool {
        for (path, hunk) in files {
            for line in hunk.lines() {
                let Some(rest) = added_line(line) else { continue };
                if rest.trim_start().starts_with("#[test]") {
                    return true;
                }
                if is_test_file(path) && !rest.trim().is_empty() {
                    return true;
                }
            }
        }
        false
    }

    /// Every id a diff cites for the first time, in a change that adds no
    /// test anywhere. Reported against every file that carries a new
    /// citation — the module doc, the header, wherever the claim was made —
    /// because a citation with no test is bare no matter which file it is in.
    pub fn bare_citations(diff: &str) -> Vec<Bare> {
        let files = split_by_file(diff);
        if diff_adds_a_test(&files) {
            return Vec::new();
        }
        let mut bare = Vec::new();
        for (path, hunk) in &files {
            for id in added_ids(hunk) {
                bare.push(Bare { id, file: path.clone() });
            }
        }
        bare.sort();
        bare.dedup();
        bare
    }
}

