                     --- a/src/tool.rs\n\
                     +++ b/src/tool.rs\n\
                     @@ -1,3 +1,6 @@\n\
                     +//! `shell` is confined to the workspace (`X-13`).\n\
                     +//!\n\
                     +//! A path outside the workspace root is refused before the process runs.\n\
                      fn shell() {}\n";
        let bare = bare_citations(diff);
        assert_eq!(bare.len(), 1);
        assert_eq!(bare[0].id, "X-13");
        assert_eq!(bare[0].file, "src/tool.rs");
    }

    /// The same citation, this time with a `#[test]` added anywhere in the
    /// diff. The claim is now backed, whatever file the test lives in.
    #[test]
    fn a_citation_with_a_new_test_anywhere_is_not_bare() {
        let diff = "diff --git a/src/tool.rs b/src/tool.rs\n\
                     --- a/src/tool.rs\n\
                     +++ b/src/tool.rs\n\
                     @@ -1,3 +1,10 @@\n\
                     +//! `shell` is confined to the workspace (`X-13`).\n\
                      fn shell() {}\n\
                     +\n\
                     +#[test]\n\
                     +fn shell_refuses_a_path_outside_the_workspace() {\n\
                     +    assert!(shell_at(\"../outside\").is_err());\n\
                     +}\n";
        assert!(bare_citations(diff).is_empty());
    }

    /// A citation added in `tests/` itself — a new integration test whose
    /// name or docstring happens to name the id — is not bare either: the
    /// test file gaining lines is the evidence, wherever the id sits.
    #[test]
    fn a_citation_backed_by_lines_added_in_a_test_file_is_not_bare() {
        let diff = "diff --git a/tests/shell.rs b/tests/shell.rs\n\
                     --- a/tests/shell.rs\n\
                     +++ b/tests/shell.rs\n\
                     @@ -1,1 +1,4 @@\n\
                     +// covers X-13\n\
                     +fn shell_stays_in_the_workspace() {\n\
                     +    assert!(run(\"../outside\").is_err());\n\
                     +}\n";
        assert!(bare_citations(diff).is_empty());
    }

    /// An id present before and after — moved, not newly cited — is not
    /// reported even with no test in the diff. `bare_citations` is about a
    /// claim being *added*, not about every file that merely mentions an id.
    #[test]
    fn an_id_only_moved_within_the_file_is_not_a_new_citation() {
        let diff = "diff --git a/src/tool.rs b/src/tool.rs\n\
                     --- a/src/tool.rs\n\
                     +++ b/src/tool.rs\n\
                     @@ -1,2 +1,2 @@\n\
                     -//! confined to the workspace (`X-13`).\n\
                     +//! `shell` stays inside the workspace (`X-13`).\n\
                      fn shell() {}\n";
        assert!(bare_citations(diff).is_empty());
    }

    /// A diff with no citation at all — most diffs — reports nothing. The
    /// check is about a claim made without proof, not about test coverage in
    /// general.
    #[test]
    fn a_diff_that_cites_nothing_is_never_bare() {
        let diff = "diff --git a/src/tool.rs b/src/tool.rs\n\
                     --- a/src/tool.rs\n\
                     +++ b/src/tool.rs\n\
                     @@ -1,1 +1,2 @@\n\
                      fn shell() {}\n\
                     +fn helper() {}\n";
        assert!(bare_citations(diff).is_empty());
    }
}

